    #[setter(build_number)]
    fn set_build_number(&mut self, value: i32) { self.0.build_number = value; }
    #[getter(version)]
    fn get_version(&self) -> u32 { self.0.version }
    #[setter(version)]
    fn set_version(&mut self, value: u32) { self.0.version = value; }
    #[getter(group_tag)]
    fn get_group_tag(&self) -> u32 { self.0.group_tag }
    #[setter(group_tag)]
    fn set_group_tag(&mut self, value: u32) { self.0.group_tag = value; }
    #[getter(group_version)]
    fn get_group_version(&self) -> u32 { self.0.group_version }
    #[setter(group_version)]
    fn set_group_version(&mut self, value: u32) { self.0.group_version = value; }
    #[getter(checksum)]
    fn get_checksum(&self) -> u32 { self.0.checksum }
    #[setter(checksum)]
    fn set_checksum(&mut self, value: u32) { self.0.checksum = value; }
