/// Parse an ASCII group-tag string (1-4 chars, e.g. `"bipd"` or
/// `"mo"`) into the BE-packed `u32` form used on disk. Short tags are
/// right-padded with spaces to 4 bytes. Returns `None` if the input
/// is longer than 4 bytes. Inverse of [`format_group_tag`].
#[pyfunction]
pub fn parse_group_tag(s: String) -> Option<u32> { blam_tags::fields::parse_group_tag(s.as_str()) }

/// Render a 4-byte group tag (stored as a BE-packed `u32` with
/// trailing-space padding for short tags) as its ASCII form, with
/// trailing spaces and NULs stripped. Matches the convention used
/// throughout the tag-file wire format. Inverse of [`parse_group_tag`].
#[pyfunction]
pub fn format_group_tag(tag: u32) -> String { blam_tags::fields::format_group_tag(tag).to_string() }

/// Register every generated class on the extension module.
pub fn register(m: &Bound<'_, PyModule>) -> PyResult<()> {
    m.add_class::<PyApiInteropData>()?;
    m.add_class::<PyArgbColor>()?;
    m.add_class::<PyEndian>()?;
    m.add_class::<PyGame>()?;
    m.add_class::<PyMatrix4>()?;
    m.add_class::<PyPoint2d>()?;
    m.add_class::<PyRealAhsvColor>()?;
    m.add_class::<PyRealArgbColor>()?;
    m.add_class::<PyRealBounds>()?;
    m.add_class::<PyRealEulerAngles2d>()?;
    m.add_class::<PyRealEulerAngles3d>()?;
    m.add_class::<PyRealHsvColor>()?;
    m.add_class::<PyRealMatrix4x3>()?;
    m.add_class::<PyRealOrientation>()?;
    m.add_class::<PyRealPlane2d>()?;
    m.add_class::<PyRealPlane3d>()?;
    m.add_class::<PyRealPoint2d>()?;
    m.add_class::<PyRealPoint3d>()?;
    m.add_class::<PyRealQuaternion>()?;
    m.add_class::<PyRealRectangle2d>()?;
    m.add_class::<PyRealRectangle3d>()?;
    m.add_class::<PyRealRgbColor>()?;
    m.add_class::<PyRealVector2d>()?;
    m.add_class::<PyRealVector3d>()?;
    m.add_class::<PyRectangle2d>()?;
    m.add_class::<PyRgbColor>()?;
    m.add_class::<PyShortBounds>()?;
    m.add_class::<PyStringIdData>()?;
    m.add_class::<PyTagFieldType>()?;
    m.add_class::<PyTagFileHeader>()?;
    m.add_class::<PyTagReferenceData>()?;
    m.add_class::<PyTitle>()?;
    m.add_function(pyo3::wrap_pyfunction!(parse_group_tag, m)?)?;
    m.add_function(pyo3::wrap_pyfunction!(format_group_tag, m)?)?;
    m.add("AngleBounds", m.getattr("RealBounds")?)?;
    m.add("FractionBounds", m.getattr("RealBounds")?)?;
    Ok(())
}
